import re

FILE = re.compile(r"^(?P<file>\S+):\s+file format (?P<format>\S+)\s*$")
SECTION = re.compile(r"^\.debug_info contents:\s*$")
UNIT = re.compile(r"^(?P<offset>0x[0-9a-f]+): Compile Unit: (?P<rest>.*?)(?: \(next unit at (?P<next_unit>0x[0-9a-f]+)\))?\s*$")
UNIT_KV = re.compile(r"(?P<key>\w+) = (?P<value>[^,]+)")
DIE = re.compile(r"^(?P<offset>0x[0-9a-f]+):(?P<indent> +)(?P<tag>DW_TAG_\w+|NULL)\s*$")
ATTR = re.compile(r"^\s+(?P<attr>DW_AT_\w+)\s+\((?P<value>.*)\)\s*$")
CONT = re.compile(r"^\s+(?P<text>\S.*?)\s*$")
QUOTED = re.compile(r'^"(?P<s>.*)"$')


def parse(lines):
    skip, files, file_lines, units, unit_lines, dies, die_lines = [], [], [], [], [], [], []
    attrs, attr_lines = [], []
    unit, stack, cur = "", [], None
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = FILE.match(ln)
        if m:
            files.append({"file": m.group("file"), "format": m.group("format")}); file_lines.append(i); continue
        if SECTION.match(ln):
            skip.append(i); continue
        m = UNIT.match(ln)
        if m:
            unit = m.group("offset")
            rec = {"offset": unit}
            for kv in UNIT_KV.finditer(m.group("rest")):
                rec[kv.group("key")] = kv.group("value").strip()
            rec["next unit"] = m.group("next_unit") or ""
            units.append(rec); unit_lines.append(i); stack = []; cur = None; continue
        m = DIE.match(ln)
        if m:
            depth = (len(m.group("indent")) - 1) // 2
            del stack[depth:]
            if m.group("tag") == "NULL":
                skip.append(i); cur = None; continue
            cur = {"unit": unit, "offset": m.group("offset"), "depth": depth,
                   "parent": stack[-1] if stack else "", "tag": m.group("tag"), "name": ""}
            stack.append(m.group("offset"))
            dies.append(cur); die_lines.append(i); last = None; continue
        if cur is None:
            continue
        m = ATTR.match(ln)
        if m:
            val = m.group("value")
            q = QUOTED.match(val)
            val = q.group("s") if q else val
            if m.group("attr") == "DW_AT_name":
                cur["name"] = val
            last = {"die": cur["offset"], "tag": cur["tag"], "attribute": m.group("attr"), "value": val}
            attrs.append(last); attr_lines.append(i); continue
        m = CONT.match(ln)
        if m and last:
            last["value"] = last["value"] + "; " + m.group("text"); attr_lines.append(i); continue
    ukeys = []
    for r in units:
        for k in r:
            if k not in ukeys:
                ukeys.append(k)
    units = [{k: r.get(k, "") for k in ukeys} for r in units]
    blocks = [{"name": "file", "kind": "table", "lines": file_lines, "records": files},
              {"name": "compile units", "kind": "table", "lines": unit_lines, "records": units},
              {"name": "dies", "kind": "table", "lines": die_lines, "records": dies},
              {"name": "attributes", "kind": "table", "lines": attr_lines, "records": attrs}]
    return {"blocks": blocks, "skip": skip}
